#include "Core.hpp"
#include "WrittenPrefix.hpp"
#include "ContentSniff.hpp"
#include <iostream>
using namespace udm;
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;auto check=[&](bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);};try{
 WrittenPrefix prefix;Bytes bytes;prefix.reset(8);check(!prefix.read(-1,bytes),"Unknown final length cannot claim a complete captured prefix");const Bytes tail{'e','f','g','h'},head{'a','b','c','d'};prefix.capture(tail.data(),tail.size(),4);check(!prefix.read(8,bytes),"A later range cannot fill an unwritten leading gap");prefix.capture(head.data(),head.size(),0);check(prefix.read(8,bytes)&&bytes==Bytes({'a','b','c','d','e','f','g','h'}),"Out-of-order committed writes reconstruct the exact leading bytes");check(prefix.read(1000000,bytes)&&bytes.size()==8,"A large representation keeps only the bounded prefix");check(prefix.read(3,bytes)&&bytes==Bytes({'a','b','c'}),"Short final bodies expose no padding beyond actual EOF");const Bytes replacement{'X','Y'};prefix.capture(replacement.data(),2,2);check(prefix.read(8,bytes)&&bytes[2]=='X'&&bytes[3]=='Y',"Overwritten prefix offsets reflect the latest successful file write");prefix.capture(nullptr,100,0);prefix.capture(head.data(),head.size(),-1);prefix.capture(head.data(),head.size(),1000000);check(prefix.read(8,bytes)&&bytes[0]=='a',"Invalid or out-of-window captures leave the verified window unchanged");prefix.reset(8);check(!prefix.read(8,bytes),"A new HTTP attempt cannot reuse the preceding representation prefix");check(prefix.read(0,bytes)&&bytes.empty(),"A proven empty body remains empty for content classification");prefix.capture(tail.data(),4,4);prefix.capture(head.data(),2,0);check(!prefix.read(6,bytes),"Coverage beyond a short body's EOF cannot disguise a leading gap");
 const std::string html="<!doctype html><html><body>rejected login page</body></html>";prefix.reset(contentSniffReadLimit);prefix.capture(reinterpret_cast<const BYTE*>(html.data()),html.size(),0);check(prefix.read(html.size(),bytes)&&sniffContent(bytes.data(),bytes.size(),true).verdict==SniffVerdict::Html,"Captured bytes preserve rejection of an HTML body served as a file");Bytes zip(64,0);zip[0]='P';zip[1]='K';zip[2]=3;zip[3]=4;prefix.reset(contentSniffReadLimit);prefix.capture(zip.data(),zip.size(),0);check(prefix.read(zip.size(),bytes)&&sniffContent(bytes.data(),bytes.size(),true).extension=="zip","Captured bytes preserve exact recognized archive content");prefix.reset(0);check(!prefix.read(1,bytes),"Unavailable optional cache falls back rather than inventing content");
 }catch(const std::exception& e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"checks",checks}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;}
